function unavailable(error,extra={}){return {ok:false,continue:true,error,...extra};}
function assertSHA(sha){if(typeof sha!=='string'||!/^[a-f0-9]{40}$/.test(sha))throw new Error('WIKI_SNAPSHOT_INVALID');return sha;}
function safePath(path){if(typeof path!=='string'||path.length>240||!/^[A-Za-z0-9_./-]+\.md$/.test(path)||path.startsWith('/')||path.includes('//')||path.split('/').some(p=>p==='.'||p==='..')||(!path.startsWith('wiki/')&&!['SCHEMA.md','README.md','index.md','log.md'].includes(path)))throw new Error('WIKI_PATH_DENIED');return path;}
function validateRequest(input){try{if(!roles.includes(input.agent)||!['search','read','skills','skill'].includes(input.mode)||typeof input.job_id!=='string'||!/^[-a-zA-Z0-9_]{1,160}$/.test(input.job_id))throw new Error('WIKI_REQUEST_INVALID');if(input.wiki_sha)assertSHA(input.wiki_sha);if(input.mode==='read')safePath(input.path);if(input.mode==='skill'&&!catalog.some(s=>s.id===input.path))throw new Error('SKILL_UNKNOWN');for(const f of ['query','domain','kind'])if(input[f]!==undefined&&(typeof input[f]!=='string'||input[f].length>500))throw new Error('WIKI_QUERY_INVALID');return {...input,ok:true,continue:true,query:input.query||'',domain:input.domain||'',kind:input.kind||''};}catch(e){return unavailable(e.message);}}
function parseManifest(text){const m=typeof text==='string'?JSON.parse(text):text;if(!m||!['1.0','1.1'].includes(m.schema_version)||!Array.isArray(m.documents))throw new Error('WIKI_MANIFEST_INVALID');const p=m.documents.map(d=>safePath(d.path));if(new Set(p).size!==p.length)throw new Error('WIKI_DUPLICATE_PATH');return m;}
function authorizePath(m,path){safePath(path);const d=m.documents.find(d=>d.path===path);if(!d)throw new Error('WIKI_DOCUMENT_NOT_LISTED');return d;}
function httpBody(r){return r?.body??r?.wiki_text??r?.data??r;}
function audit(r,path,status,http_status){return {job_id:r.job_id,agent:r.agent,path,sha:r.wiki_sha||null,status,http_status,read_at:new Date().toISOString()};}
function pageResult(r,m,response){try{const d=authorizePath(m,r.path);assertSHA(r.wiki_sha);const status=Number(response?.statusCode??(response?.error?0:200)),body=httpBody(response);const ok=status>=200&&status<300&&typeof body==='string'&&body.length>0&&body.length<=120000;const read_log=audit(r,r.path,ok?'ok':'error',status);return ok?{ok:true,continue:true,path:r.path,title:d.title,version:m.release,sha:r.wiki_sha,content:body,links:d.links||[],read_log}:unavailable('WIKI_READ_UNAVAILABLE',{path:r.path,sha:r.wiki_sha,read_log});}catch(e){return unavailable(e.message,{read_log:audit(r,r.path,'denied',0)});}}
function searchPages(m,{query='',domain='',kind=''}={}){const norm=s=>String(s).normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase(),tokens=norm(query).split(/[^a-z0-9]+/).filter(t=>t.length>1).slice(0,20);const rows=m.documents.filter(d=>(!domain||d.domain===domain)&&(!kind||d.kind===kind)).map(d=>({d,score:tokens.reduce((s,t)=>s+Number(norm([d.path,d.title,d.summary,...(d.tags||[])].join(' ')).includes(t)),0)})).filter(r=>!tokens.length||r.score>0).sort((a,b)=>b.score-a.score||a.d.path.localeCompare(b.d.path));return {ok:true,continue:true,method:'classified_keyword_index_guided_by_agent',results:rows.slice(0,8).map(r=>r.d),has_more:rows.length>8};}
