]/.test(r.title)||typeof r.body!=='string'||r.body.length<30||r.body.length>30000)throw new Error('WIKI_WRITE_DENIED');const slug=r.title.normalize('NFKD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60);if(!slug)throw new Error('WIKI_TITLE_INVALID');const path=`wiki/records/${r.job_id}-${slug}.md`,date=new Date().toISOString().slice(0,10);const content=`---
