- '+link+' — '+r.kind+'/'+r.domain+'; proposed.
';const nextLog=log+'
- '+r.date+' — Architetto, job '+r.job_id+': registrato '+link+' come proposed.
';const g=structuredClone(graph);g.edges.push({from:'index',to:r.path.slice(0,-3),relation:'references'},{from:'log',to:r.path.slice(0,-3),relation:'references'},...links.map(to=>({from:r.path.slice(0,-3),to,relation:'references'})));g.backlinks={};for(const e of g.edges)(g.backlinks[e.to]??=[]).push(e.from);for(const k of Object.keys(g.backlinks))g.backlinks[k]=[...new Set(g.backlinks[k])];return {ok:true,base_tree:baseTree,path:r.path,tree:[{path:'LLMWIKI/'+r.path,mode:'100644',type:'blob',content:r.content},{path:'LLMWIKI/manifest.json',mode:'100644',type:'blob',content:JSON.stringify(next,null,2)+'
'},{path:'LLMWIKI/index.md',mode:'100644',type:'blob',content:nextIndex},{path:'LLMWIKI/log.md',mode:'100644',type:'blob',content:nextLog},{path:'LLMWIKI/graph.json',mode:'100644',type:'blob',content:JSON.stringify(g,null,2)+'
'}]};}catch(e){return unavailable(e.message);}}

